# Monte Carlo check of SimCohorts()
#
# Run from the package root, after devtools::load_all() or
# library(OncoCohortSelect):
#   source("inst/validation/validate_simcohorts.R")
# Writes inst/validation/output/validate_simcohorts.csv and
# inst/validation/output/validate_simcohorts.md (generated, do not edit by hand).
#
# Without a cutoff and dropout, the simulated response rate, adverse event
# rate and PFS median of each cohort are compared with the inputs, and the
# adverse event is checked to be uncorrelated with response and PFS. PASS when
# the difference is within 4 Monte Carlo standard errors. Run time: a few
# seconds.

if (!exists("SimCohorts")) library(OncoCohortSelect)
out_dir <- file.path("inst", "validation", "output")
dir.create(out_dir, showWarnings = FALSE, recursive = TRUE)

inputs <- data.frame(group = c("Cohort1", "Cohort2"), pfs.median = c(8, 6),
                     orr = c(0.45, 0.30), ae.rate = c(0.35, 0.20))
arms <- list(
  Cohort1 = CorOncoEndpoints::OncoArm(pfs.median = 8, orr = 0.45, resp.cor = 0.4,
                                      death.prop = 0.15, os.median = 18),
  Cohort2 = CorOncoEndpoints::OncoArm(pfs.median = 6, orr = 0.30, resp.cor = 0.4,
                                      death.prop = 0.15, os.median = 15))
nsim <- 2000
n <- c(50, 50)
d <- SimCohorts(nsim = nsim, n = n, arms = arms, ae.rate = inputs$ae.rate, seed = 7)

rows <- list()
add <- function(group, quantity, expected, computed, se) {
  tol <- 4 * se
  rows[[length(rows) + 1L]] <<- data.frame(
    group = group, quantity = quantity, expected = expected, computed = computed,
    abs_diff = abs(computed - expected), tolerance = tol,
    judgment = if (abs(computed - expected) <= tol) "PASS" else "FAIL",
    stringsAsFactors = FALSE)
}
for (j in 1:2) {
  s <- d[d$group == inputs$group[j], ]
  N <- nrow(s)
  add(inputs$group[j], "number of patients", nsim * n[j], N, 0)
  add(inputs$group[j], "response rate", inputs$orr[j], mean(s$response),
      sqrt(inputs$orr[j] * (1 - inputs$orr[j]) / N))
  add(inputs$group[j], "adverse event rate", inputs$ae.rate[j], mean(s$ae),
      sqrt(inputs$ae.rate[j] * (1 - inputs$ae.rate[j]) / N))
  # all PFS times are events without cutoff and dropout; the sample median of an
  # exponential distribution with median m has standard error m / (log(2) sqrt(N))
  add(inputs$group[j], "all PFS times are events", 1, mean(s$pfs_event), 0)
  add(inputs$group[j], "PFS median", inputs$pfs.median[j], stats::median(s$pfs_tte),
      inputs$pfs.median[j] / (log(2) * sqrt(N)))
  add(inputs$group[j], "correlation of AE and response", 0, stats::cor(s$ae, s$response),
      1 / sqrt(N))
  add(inputs$group[j], "rank correlation of AE and PFS", 0,
      stats::cor(s$ae, rank(s$pfs_tte)), 1 / sqrt(N))
}
res <- do.call(rbind, rows)
utils::write.csv(res, file.path(out_dir, "validate_simcohorts.csv"), row.names = FALSE)
fmt <- function(x) formatC(x, digits = 6, format = "g")
md <- c("# Monte Carlo check of SimCohorts()", "",
        paste0("Generated by inst/validation/validate_simcohorts.R on ", Sys.Date(), " with ",
               nsim, " simulated trials of ", n[1], " patients per cohort."), "",
        paste0("Judgments: ", paste(names(table(res$judgment)), table(res$judgment),
                                    sep = " = ", collapse = ", "), "."), "",
        "| Cohort | Quantity | Expected | Simulated | Difference | Tolerance | Judgment |",
        "|---|---|---|---|---|---|---|",
        paste0("| ", res$group, " | ", res$quantity, " | ", fmt(res$expected), " | ",
               fmt(res$computed), " | ", fmt(res$abs_diff), " | ", fmt(res$tolerance), " | ",
               res$judgment, " |"))
writeLines(md, file.path(out_dir, "validate_simcohorts.md"))
print(table(res$judgment))
if (any(res$judgment == "FAIL")) warning("Some checks failed.")
